{
  "type": "object",
  "strict": true,
  "$defs": {
    "comment": {
      "type": "object",
      "strict": true,
      "fields": {
        "body": { "type": "string", "rules": [["required"], ["maxLength", 40]] },
        "replies": { "type": "array", "of": { "$ref": "comment" } }
      }
    }
  },
  "fields": {
    "email": { "type": "string", "rules": [["required"], ["pattern", "^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$"]] },
    "password": { "type": "string", "rules": [["required"], ["minLength", 8], ["pattern", "[0-9]"]] },
    "confirm": { "type": "string", "rules": [["required"], ["matches", "password"]] },
    "age": { "type": "number", "coerce": true, "rules": [["required"], ["integer"], ["min", 13], ["max", 120]] },
    "terms": { "type": "boolean", "coerce": true, "rules": [["required"], ["oneOf", [true]]] },
    "tags": {
      "type": "array",
      "rules": [["maxLength", 3], ["unique", null]],
      "of": { "type": "string", "rules": [["minLength", 2]] }
    },
    "address": {
      "type": "object",
      "fields": {
        "city": { "type": "string", "rules": [["required"]] },
        "zip": { "type": "string", "rules": [["pattern", "^[0-9]{5}$"]] }
      }
    },
    "plan": { "type": "string", "rules": [["required"], ["oneOf", ["free", "pro"]]] },
    "seats": {
      "type": "number",
      "coerce": true,
      "when": ["plan", "eq", "pro"],
      "rules": [["required"], ["integer"], ["min", 2]]
    },
    "comments": { "type": "array", "of": { "$ref": "comment" } },
    "items": {
      "type": "array",
      "of": {
        "type": "object",
        "fields": {
          "sku": { "type": "string", "rules": [["required"], ["pattern", "^[A-Z]{2}-[0-9]{4}$"]] },
          "qty": { "type": "number", "coerce": true, "rules": [["required"], ["integer"], ["min", 1]] }
        }
      }
    }
  }
}

