'use strict';
// MESSAGE CATALOGUE v1 - one template per rule code, and the single place a message is built.
// Do not edit. {path} is the failing path and {arg} is the rule's argument: a string argument is
// inserted as it is, anything else through JSON.stringify.

const MESSAGES = {
  required: '{path} is required',
  type: '{path} must be a {arg}',
  minLength: '{path} must be at least {arg} long',
  maxLength: '{path} must be at most {arg} long',
  pattern: '{path} has the wrong format',
  min: '{path} must be {arg} or more',
  max: '{path} must be {arg} or less',
  integer: '{path} must be a whole number',
  oneOf: '{path} must be one of {arg}',
  matches: '{path} must equal {arg}',
  unique: '{path} must not repeat a value',
  unknown: '{path} is not allowed here'
};

function messageFor(code, path, arg) {
  const tpl = MESSAGES[code] || '{path} is invalid';
  const a = typeof arg === 'string' ? arg : JSON.stringify(arg);
  return tpl.split('{path}').join(path).split('{arg}').join(a);
}

module.exports = { MESSAGES: MESSAGES, messageFor: messageFor };

