'use strict';
// CONTRACT SPEC for the validation engine.   Run:  node tests/validate.spec.js
// Do not edit this file. Every case names the rule it enforces.
const assert = require('assert');
let V;
try {
  V = require('../src/validate.js');
} catch (e) {
  console.error('cannot load src/validate.js: ' + e.message);
  console.error('it must be CommonJS ending in: module.exports = { validate, registerRule };');
  process.exit(1);
}
const SCHEMA = require('../schema/signup.json');
let n = 0;
function eq(got, want, msg) {
  assert.strictEqual(got, want, msg + '\n  got  ' + got + '\n  want ' + want);
  n++;
}
const OK = {
  email: 'a.b+c@example.co.uk', password: 'hunter42x', confirm: 'hunter42x',
  age: '13', terms: 'true', tags: ['dev', 'ops'],
  address: { city: 'Vilnius', zip: '01100' },
  plan: 'free',
  comments: [{ body: 'hi', replies: [{ body: 'there' }] }],
  items: [{ sku: 'AB-1234', qty: '2' }]
};
function withOk(patch) {
  const d = JSON.parse(JSON.stringify(OK));
  for (const k of Object.keys(patch)) {
    if (patch[k] === '__drop__') delete d[k]; else d[k] = patch[k];
  }
  return d;
}
function codes(data) {
  return V.validate(SCHEMA, data).errors.map(function (e) { return e.path + ':' + e.code; }).join('|');
}

// [ rule, data, expected "path:code" list in order ]
const CASES = [
  ['a complete, well formed signup has no errors', OK, ''],
  ['an empty object reports every required field, in schema order', {},
    'email:required|password:required|confirm:required|age:required|terms:required|plan:required'],
  ['a whitespace-only string counts as missing', withOk({ email: '   ' }), 'email:required'],
  ['an absent optional branch is not an error',
    withOk({ tags: '__drop__', address: '__drop__', items: '__drop__', comments: '__drop__' }), ''],
  ['a malformed email fails its pattern', withOk({ email: 'nope@nope' }), 'email:pattern'],
  ['only the FIRST failing rule of a path is reported',
    withOk({ password: 'ab1', confirm: 'ab1' }), 'password:minLength'],
  ['rules run in declaration order, so a long password without a digit fails the pattern',
    withOk({ password: 'longenough', confirm: 'longenough' }), 'password:pattern'],
  ['matches compares against the named sibling', withOk({ confirm: 'other123' }), 'confirm:matches'],
  ['length counts JavaScript string length, so accented letters still count once',
    withOk({ password: 'héllo12', confirm: 'héllo12' }), 'password:minLength'],
  ['a coercible numeric string is validated as the number it becomes',
    withOk({ age: '12' }), 'age:min'],
  ['a non-integer number fails before the range rules', withOk({ age: '13.5' }), 'age:integer'],
  ['a string that is not plain digits does not coerce, so it fails the type check',
    withOk({ age: '1e3' }), 'age:type'],
  ['above the maximum fails too', withOk({ age: '121' }), 'age:max'],
  ['a coerced boolean is checked against oneOf', withOk({ terms: 'false' }), 'terms:oneOf'],
  ['maxLength on an array counts its items', withOk({ tags: ['aa', 'bb', 'cc', 'dd'] }), 'tags:maxLength'],
  ['an error on the array itself stops its items being checked',
    withOk({ tags: ['a', 'b', 'c', 'd'] }), 'tags:maxLength'],
  ['unique rejects a repeated item', withOk({ tags: ['dev', 'dev'] }), 'tags:unique'],
  ['an item error is reported at its indexed path', withOk({ tags: ['dev', 'x'] }), 'tags[1]:minLength'],
  ['a nested object reports a dotted path',
    withOk({ address: { zip: '01100' } }), 'address.city:required'],
  ['and its other fields keep their own paths',
    withOk({ address: { city: 'V', zip: '1' } }), 'address.zip:pattern'],
  ['errors inside an array of objects come out in index then field order',
    withOk({ items: [{ sku: 'AB-1234', qty: '0' }, { sku: 'bad', qty: '1' }] }),
    'items[0].qty:min|items[1].sku:pattern'],
  ['a wrong shape in an array is a type error at that index',
    withOk({ items: ['x'] }), 'items[0]:type'],
  ['a missing required field inside an array element is found too',
    withOk({ items: [{ qty: '1' }] }), 'items[0].sku:required'],
  ['a guarded field is skipped entirely while its guard is false',
    withOk({ plan: 'free', seats: 'not a number at all' }), ''],
  ['and becomes required the moment the guard holds', withOk({ plan: 'pro' }), 'seats:required'],
  ['a guarded field that is present is validated like any other',
    withOk({ plan: 'pro', seats: '1' }), 'seats:min'],
  ['the guard itself is checked too', withOk({ plan: 'gold' }), 'plan:oneOf'],
  ['a $ref node is replaced by the definition it names',
    withOk({ comments: [{ body: 'x'.repeat(41) }] }), 'comments[0].body:maxLength'],
  ['and a definition may reference itself, so the tree can be any depth',
    withOk({ comments: [{ body: 'ok', replies: [{ body: 'y'.repeat(41) }] }] }),
    'comments[0].replies[0].body:maxLength'],
  ['three levels down is no different',
    withOk({ comments: [{ body: 'a', replies: [{ body: 'b', replies: [{ body: '' }] }] }] }),
    'comments[0].replies[0].replies[0].body:required'],
  ['a strict object rejects a key it does not declare',
    withOk({ surprise: 1 }), 'surprise:unknown'],
  ['including inside a referenced definition',
    withOk({ comments: [{ body: 'ok', extra: true }] }), 'comments[0].extra:unknown'],
  ['unknown keys are reported after every declared field, in the input order',
    { email: 'nope@nope', password: 'hunter42x', confirm: 'hunter42x', age: '13', terms: 'true',
      plan: 'free', zzz: 1, aaa: 2 },
    'email:pattern|zzz:unknown|aaa:unknown']
];
for (const [rule, data, want] of CASES) eq(codes(data), want, rule);

const res = V.validate(SCHEMA, OK);
eq(res.valid, true, 'valid is true exactly when there are no errors');
eq(res.value.age, 13, 'the returned value carries the coerced number');
eq(res.value.terms, true, 'and the coerced boolean');
eq(res.value.items[0].qty, 2, 'coercion reaches inside arrays of objects');
eq('seats' in V.validate(SCHEMA, withOk({ plan: 'free', seats: '9' })).value, false,
  'a field whose guard is false is dropped from the returned value');
eq(V.validate(SCHEMA, withOk({ plan: 'pro', seats: '4' })).value.seats, 4,
  'and is coerced normally once the guard holds');
eq(typeof OK.age, 'string', 'the input object must not be touched');
eq(JSON.stringify(V.validate(SCHEMA, OK).value.address), '{"city":"Vilnius","zip":"01100"}',
  'untouched branches are copied through');

const msgs = V.validate(SCHEMA, withOk({ age: '12', tags: ['dev', 'dev'], items: [{ sku: 'bad', qty: '1' }] })).errors;
eq(msgs.map(function (e) { return e.message; }).join(' / '),
  'age must be 13 or more / tags must not repeat a value / items[0].sku has the wrong format',
  'every message comes from the catalogue in src/messages.js, with {path} and {arg} filled in');

V.registerRule('startsWith', function (value, arg) { return String(value).indexOf(arg) === 0; });
const custom = { type: 'object', fields: { code: { type: 'string', rules: [['required'], ['startsWith', 'X']] } } };
eq(V.validate(custom, { code: 'Yes' }).errors.map(function (e) { return e.path + ':' + e.code; }).join('|'),
  'code:startsWith', 'a registered rule is usable by name');
eq(V.validate(custom, { code: 'Xes' }).valid, true, 'and passes when it should');
assert.throws(function () {
  V.validate({ type: 'object', fields: { a: { type: 'string', rules: [['nope']] } } }, { a: 'x' });
}, /unknown rule: nope/, 'a rule nobody registered is an error, not a silent pass'); n++;
assert.throws(function () {
  V.validate({ type: 'object', $defs: {}, fields: { a: { $ref: 'ghost' } } }, { a: 'x' });
}, /unknown \$ref: ghost/, 'a $ref to a definition that does not exist is an error'); n++;

console.log('ok ' + n + ' assertions');
